const stories = [
{date:'3 APR 2019',title:'The rugby dinner that brought Hong Kong together',text:'A sold-out dinner at the Grand Hyatt raised HK$5 million for the Foundation ahead of the Hong Kong Sevens, as reported by the South China Morning Post.',source:'SOUTH CHINA MORNING POST · 5 APR 2019',type:'press',url:'https://www.scmp.com/sport/rugby/hk-sevens/article/3004691/hong-kong-sevens-doddie-weir-talks-motor-neurone-disease'},
{date:'12–18 OCT 2020',title:'Going the extra mile — 5,911 of them',text:'Hong Kong Scottish’s virtual walking and running challenge brought the rugby community together to support the Doddie Weir Foundation and local homelessness charity ImpactHK.',source:'SOUTH CHINA MORNING POST · 23 OCT 2020',type:'press',url:'https://www.scmp.com/sport/rugby/article/3106643/hong-kong-scottishs-i-would-walk-5911-miles-fundraiser-goes-extra-mile'},
{date:'2023',title:'Putting down roots in Hong Kong',text:'The Foundation registered as an official Hong Kong charity, strengthening the city’s connection to its research mission and support for people living with MND.',source:'FOUNDATION · OUR HISTORY & FOUNDER',type:'foundation',url:'https://www.myname5doddie.co.uk/about-us/our-history-and-founder/'},
{date:'3 APR 2024',title:'An evening of generosity at the Grand Hyatt',text:'Over 500 guests, including Doddie’s son Hamish, attended the annual dinner. The Foundation reported £400,000 raised for MND research.',source:'FOUNDATION · 12 APR 2024',type:'foundation',url:'https://www.myname5doddie.co.uk/news-and-stories/the-2024-hong-kong-doddie-dinner/'},
{date:'30 SEP 2024',title:'Hong Kong Scottish joins the team',text:'A fundraising partnership for the 2024–25 season brought the Foundation onto the front of the club’s jerseys, with fundraising and support across its sections.',source:'FOUNDATION · 30 SEP 2024',type:'foundation',url:'https://www.myname5doddie.co.uk/news-and-stories/hong-kong-scottish-rfc-announces-fundraising-partnership-with-my-name5-doddie-foundation/'}
];
const archive=document.querySelector('#archive');
function renderStories(filter='all'){archive.replaceChildren();stories.filter(s=>filter==='all'||s.type===filter).forEach(s=>{const row=document.createElement('article');row.className='archive-row';const date=document.createElement('div');date.className='archive-date';date.textContent=s.date;const body=document.createElement('div');const title=document.createElement('h3');title.textContent=s.title;const desc=document.createElement('p');desc.textContent=s.text;const source=document.createElement('small');source.textContent=s.source;body.append(title,desc,source);const link=document.createElement('a');link.href=s.url;link.target='_blank';link.rel='noopener';link.textContent='Read the story ↗';row.append(date,body,link);archive.append(row);});}
renderStories();document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(el=>{el.classList.toggle('active',el===b);el.setAttribute('aria-pressed',String(el===b));});renderStories(b.dataset.filter);}));
const defaults=[{date:'JAN 2027',title:'Harbour Steps for Doddie',location:'Proposed: Central waterfront',description:'A relaxed community walk with a splash of tartan. Bring friends, take in the harbour and start the year with a shared purpose.'},{date:'MAR 2027',title:'One Team, One Goal',location:'Proposed: Hong Kong rugby community venue',description:'An afternoon of friendly touch rugby, family activities and fundraising. A chance for every generation to get involved.'},{date:'APR 2027',title:'A Touch of Tartan Dinner',location:'Proposed: Hong Kong hotel venue',description:'An idea for an evening of rugby stories, good company and an auction in support of MND research.'}];
const key='doddie-hk-draft-events-v1';let events=structuredClone(defaults);try{const saved=JSON.parse(localStorage.getItem(key));if(Array.isArray(saved)&&saved.length===3&&saved.every(e=>['date','title','location','description'].every(k=>typeof e[k]==='string'&&e[k].length<=1000)))events=saved;}catch{}
function renderEvents(){const list=document.querySelector('#events-list');list.replaceChildren();events.forEach(e=>{const row=document.createElement('article');row.className='event-row';const date=document.createElement('div');date.className='event-date';date.textContent=e.date;const small=document.createElement('small');small.textContent='PROPOSED';date.append(small);const body=document.createElement('div');const h=document.createElement('h3');h.textContent=e.title;const p=document.createElement('p');p.textContent=e.description;const location=document.createElement('p');location.textContent=e.location;body.append(h,p,location);const label=document.createElement('span');label.className='label';label.textContent='Draft concept';row.append(date,body,label);list.append(row);});}
function renderEditor(){const form=document.querySelector('#editor-form');form.replaceChildren();events.forEach((e,i)=>{const group=document.createElement('fieldset');group.className='edit-group';const legend=document.createElement('legend');legend.textContent=`Event idea ${i+1}`;group.append(legend);['date','title','location','description'].forEach(k=>{const label=document.createElement('label');label.textContent={date:'Proposed month / year',title:'Event name',location:'Proposed location',description:'Description'}[k];const field=document.createElement(k==='description'?'textarea':'input');field.name=`${i}-${k}`;field.value=e[k];field.required=true;field.maxLength=k==='description'?600:150;if(k==='description')field.rows=3;label.append(field);group.append(label);});form.append(group);});}
renderEvents();renderEditor();document.querySelector('#editor-form').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.currentTarget);events=events.map((_,i)=>Object.fromEntries(['date','title','location','description'].map(k=>[k,String(data.get(`${i}-${k}`)).trim()])));renderEvents();try{localStorage.setItem(key,JSON.stringify(events));document.querySelector('#save-status').textContent='Saved in this browser. Export your programme to keep a shareable copy.';}catch{document.querySelector('#save-status').textContent='Updated for this visit. Browser storage is unavailable; export to keep your changes.';}});
document.querySelector('#export').addEventListener('click',()=>{const blob=new Blob([JSON.stringify({status:'Unconfirmed illustrative event concepts',events},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='doddie-hong-kong-draft-programme.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});document.querySelector('#reset').addEventListener('click',()=>{events=structuredClone(defaults);try{localStorage.removeItem(key);}catch{}renderEvents();renderEditor();document.querySelector('#save-status').textContent='Original draft ideas restored.';});
